--DS d_script_production_components
SELECT DISTINCT p21_view_production_components.order_no, p21_view_production_components.item_id, p21_view_production_components.qty_per_assembly, p21_view_production_components.oe_line_uid, p21_view_production_components.parent_oe_line_uid, p21_view_production_components.unit_of_measure, p21_view_production_components.unit_size, p21_view_production_components.assembly, p21_view_production_components.pricing_unit, p21_view_production_components.unit_price, p21_view_production_components.extended_price, p21_view_production_components.pricing_unit_size,p21_view_production_components.qty_ordered,p21_view_production_components.item_desc,p21_view_production_components.level_label,p21_view_production_components.pricing_option,0.0 parent_qty,p21_view_production_components.line_no,p21_view_production_components.extended_desc,p21_view_production_components.service_labor_id,p21_view_production_components.service_labor_desc,p21_view_production_components.service_labor_uid,p21_view_production_components.primary_bin,prod_order_line_component.loose_ship_flag,p21_view_production_components.line_seq_noFROM p21_view_production_componentsLEFT JOIN prod_ord_line_compnt_x_oe_line ON prod_ord_line_compnt_x_oe_line.oe_line_uid = p21_view_production_components.oe_line_uidLEFT JOIN prod_order_line_component ON prod_order_line_component.prod_order_line_component_uid = prod_ord_line_compnt_x_oe_line.prod_order_line_component_uidWHERE p21_view_production_components.order_no IN ('1088925')AND (COALESCE(prod_order_line_component.qty_requested, 0) <> COALESCE(prod_order_line_component.qty_canceled,0) OR COALESCE(prod_order_line_component.qty_requested, 0)=0)	